/// @notice Original six-family admission facts read only from fixed semantic owners.
/// @dev Complete journal traversal, exclusion policy and selected-branch decisions belong to the
/// fixed selector. No caller-provided record body or replacement pointer is accepted here.
library StreamArtistRecoveryRewindRecordReads {
    struct Facts {
        W.SelectedRecordV3 selected;
        R.ProvisionalAssociation association;
        R.TransitionState transition;
        uint64 admissionRevision;
        uint8 authorityClass;
        bool eligible;
        bytes32 previousRecordHash;
        bytes32 previousValueHash;
        bytes32 valueHash;
        bytes32 pairedDirective;
        address account;
        bytes32 retirementHash;
        uint32 grantedCapabilities;
        uint32 forbiddenCapabilities;
        bool granted;
        bytes32 abandonmentHash;
    }

    function read(
        W.EnvironmentV3 memory e,
        W.RecordKind kind,
        bytes32 artistId,
        uint256 nativeIndex
    ) public view returns (Facts memory) {
        return _read(e, kind, artistId, nativeIndex, bytes32(0));
    }

    /// @dev The selector derives this head from each preceding same-artist native58, in receipt
    /// order. The continuation body and both original replay admissions are still checked here.
    function readWithRevisionContinuation(
        W.EnvironmentV3 memory e,
        bytes32 artistId,
        uint256 nativeIndex,
        bytes32 originalContinuation
    ) public view returns (Facts memory) {
        return _read(e, W.RecordKind.IDENTITY_REVISION, artistId, nativeIndex, originalContinuation);
    }

    function _read(
        W.EnvironmentV3 memory e,
        W.RecordKind kind,
        bytes32 artistId,
        uint256 nativeIndex,
        bytes32 originalContinuation
    ) private view returns (Facts memory f) {
        A.environment(e);
        if (artistId == 0 || kind == W.RecordKind.GUARDIAN_SET) {
            revert W.InvalidRecoveryRewindRecord(artistId);
        }
        address owner = kind == W.RecordKind.PAYOUT_DESIGNATION ? e.payoutOwner : e.identityOwner;
        if (nativeIndex >= IStreamArtistNativeReceipts(owner).artistNativeReceiptCount()) {
            revert W.InvalidRecoveryRewindRecord(bytes32(nativeIndex));
        }
        N.Receipt memory row = IStreamArtistNativeReceipts(owner).artistNativeReceiptAt(nativeIndex);
        if (
            row.artistId != artistId || row.collectionId != 0 || row.recordHash == 0
                || row.operation != _operation(kind)
        ) {
            revert W.InvalidRecoveryRewindRecord(row.recordHash);
        }
        if (kind == W.RecordKind.SUCCESSOR_DESIGNATION) {
            f = _designation(e, artistId, row.recordHash);
        } else if (kind == W.RecordKind.ESTATE_DIRECTIVE) {
            f = _directive(e, artistId, row.recordHash);
        } else if (kind == W.RecordKind.IDENTITY_REVISION) {
            f = _revision(e, artistId, row.recordHash, originalContinuation);
        } else if (kind == W.RecordKind.PAYOUT_DESIGNATION) {
            f = _payout(e, artistId, row.recordHash);
        } else if (kind == W.RecordKind.STEWARD_SANCTION_GRANT) {
            f = _grant(e, artistId, row.recordHash);
        } else {
            f = _standing(e, artistId, row.recordHash);
        }
        f.selected.recordHash = row.recordHash;
        f.selected.nativeIndex = nativeIndex;
        f.selected.admissionProof = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERY_REWIND_RECORD_FACTS_V3"),
                uint16(3),
                e,
                kind,
                row,
                nativeIndex,
                f
            )
        );
    }

    function _designation(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 hash)
        private
        view
        returns (Facts memory f)
    {
        S.DesignationRecord memory r =
            IStreamArtistSuccessionReads(e.identityOwner).successorDesignationRecord(hash);
        T.Authorization memory auth = T.Authorization(r.nonce, r.signedAt, new bytes(0));
        if (
            r.recordHash != hash || r.terms.artistId != artistId || r.signer == address(0)
                || r.authorityClass != 1 || r.signedAt == 0 || r.signedAt > block.timestamp
                || r.terms.successor == address(0)
                || (r.terms.successorKind != 1 && r.terms.successorKind != 2)
                || r.terms.grantedCapabilities & ~uint32(4095) != 0
                || SH.designationRecord(A.hashes(e), r.terms, auth) != hash
        ) revert W.InvalidRecoveryRewindRecord(hash);
        T.ReplayCell memory n =
            A.nonce(e, artistId, r.nonce, SH.designationDigest(A.hashes(e), r.terms, auth));
        T.ReplayCell memory admitted = A.consumed(
            e,
            keccak256("identity_authority.replay.succession_chain"),
            keccak256(abi.encode(hash)),
            hash
        );
        _sameRevision(hash, n, admitted);
        f.selected.originalDataHash = keccak256(abi.encode(r));
        f.selected.nonce = r.nonce;
        f.association = r.provisional;
        f.admissionRevision = n.touchedRevision;
        f.authorityClass = r.authorityClass;
        f.pairedDirective = r.terms.directiveHash;
        f.account = r.terms.successor;
        f.grantedCapabilities = r.terms.grantedCapabilities;
        _association(e, artistId, r.signer, f);
        f.selected.admissionProof = keccak256(abi.encode(f.selected.admissionProof, n, admitted));
    }

    function _directive(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 hash)
        private
        view
        returns (Facts memory f)
    {
        S.DirectiveRecord memory r =
            IStreamArtistSuccessionReads(e.identityOwner).estateDirectiveRecord(hash);
        T.Authorization memory auth = T.Authorization(r.nonce, r.signedAt, new bytes(0));
        bytes memory payload =
            IStreamArtistSuccessionReads(e.identityOwner).estateDirectivePayload(hash);
        if (
            r.recordHash != hash || r.terms.artistId != artistId || r.signer == address(0)
                || r.authorityClass != 1 || r.signedAt == 0 || r.signedAt > block.timestamp
                || (r.terms.grantedCapabilities | r.terms.forbiddenCapabilities) & ~uint32(4095)
                    != 0 || r.terms.grantedCapabilities & r.terms.forbiddenCapabilities != 0
                || payload.length == 0 || payload.length > 8192
                || keccak256(payload) != r.terms.directivePayloadHash
                || SH.directiveRecord(A.hashes(e), r.terms, auth) != hash
        ) revert W.InvalidRecoveryRewindRecord(hash);
        T.ReplayCell memory n =
            A.nonce(e, artistId, r.nonce, SH.directiveDigest(A.hashes(e), r.terms, auth));
        T.ReplayCell memory admitted = A.consumed(
            e,
            keccak256("identity_authority.replay.directive_chain"),
            keccak256(abi.encode(hash)),
            hash
        );
        _sameRevision(hash, n, admitted);
        f.selected.originalDataHash = keccak256(abi.encode(r, payload));
        f.selected.nonce = r.nonce;
        f.association = r.provisional;
        f.admissionRevision = n.touchedRevision;
        f.authorityClass = r.authorityClass;
        f.valueHash = r.terms.directivePayloadHash;
        f.grantedCapabilities = r.terms.grantedCapabilities;
        f.forbiddenCapabilities = r.terms.forbiddenCapabilities;
        _association(e, artistId, r.signer, f);
        f.selected.admissionProof = keccak256(abi.encode(f.selected.admissionProof, n, admitted));
    }

    function _grant(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 hash)
        private
        view
        returns (Facts memory f)
    {
        Grant.GrantRecord memory r = Grant(e.identityOwner).stewardSanctionGrantRecord(hash);
        if (
            r.recordHash != hash || r.terms.artistId != artistId || r.signer == address(0)
                || r.authorityClass != 1 || r.signedAt == 0 || r.signedAt > block.timestamp
                || r.terms.statementHash == 0
                || hash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_STEWARD_SANCTION_GRANT_RECORD_V1"),
                            e.chainId,
                            e.registry,
                            artistId,
                            r.terms.granted,
                            r.terms.statementHash,
                            r.signer,
                            uint8(1),
                            r.nonce,
                            r.signedAt
                        )
                    )
        ) revert W.InvalidRecoveryRewindRecord(hash);
        bytes32 digest = H.typed(
            A.hashes(e),
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamStewardSanctionGrant(bytes32 artistId,bool granted,bytes32 statementHash,uint256 nonce,uint64 signedAt)"
                    ),
                    artistId,
                    r.terms.granted,
                    r.terms.statementHash,
                    r.nonce,
                    r.signedAt
                )
            )
        );
        T.ReplayCell memory n = A.nonce(e, artistId, r.nonce, digest);
        T.ReplayCell memory admitted = A.consumed(
            e, keccak256("identity_authority.replay.grant_chain"), keccak256(abi.encode(hash)), hash
        );
        _sameRevision(hash, n, admitted);
        f.selected.originalDataHash = keccak256(abi.encode(r));
        f.selected.nonce = r.nonce;
        f.association = r.provisional;
        f.admissionRevision = n.touchedRevision;
        f.authorityClass = 1;
        f.granted = r.terms.granted;
        f.valueHash = r.terms.statementHash;
        _association(e, artistId, r.signer, f);
        f.selected.admissionProof = keccak256(abi.encode(f.selected.admissionProof, n, admitted));
    }

    function _revision(
        W.EnvironmentV3 memory e,
        bytes32 artistId,
        bytes32 hash,
        bytes32 originalContinuation
    ) private view returns (Facts memory f) {
        Doc.Record memory r = IStreamArtistIdentityRevisionReads(e.identityOwner)
            .identityRevisionRecord(hash);
        bytes memory document = IStreamArtistIdentityRevisionReads(e.identityOwner)
            .identityDocumentBytes(r.revisedRecordHash);
        bool living = _revisionHash(e, r, 1) == hash;
        bool estate = _revisionHash(e, r, 3) == hash;
        if (
            r.recordHash != hash || r.artistId != artistId || r.signer == address(0)
                || r.signedAt == 0 || r.signedAt > block.timestamp || living == estate
                || (r.authorityClass != 1 && r.authorityClass != 3)
                || (living && r.authorityClass != 1) || r.previousRecordHash == 0
                || r.revisedRecordHash == r.previousRecordHash || document.length == 0
                || document.length > 8192 || keccak256(document) != r.revisedRecordHash
                || bytes(r.displayName).length == 0 || bytes(r.displayName).length > 256
                || bytes(r.identityRecordURI).length > 2048
        ) revert W.InvalidRecoveryRewindRecord(hash);
        _revisionParent(e, r);
        bytes32 digest = H.typed(
            A.hashes(e),
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistIdentityRevision(bytes32 artistId,bytes32 previousRecordHash,bytes32 revisedRecordHash,uint256 nonce,uint64 signedAt)"
                    ),
                    artistId,
                    r.previousRecordHash,
                    r.revisedRecordHash,
                    r.nonce,
                    r.signedAt
                )
            )
        );
        T.ReplayCell memory n = A.nonce(e, artistId, r.nonce, digest);
        bytes32 chainProof = C.revision(e, r, originalContinuation, n);
        f.selected.originalDataHash = keccak256(abi.encode(r, document));
        f.selected.nonce = r.nonce;
        f.association = IStreamArtistRotationReads(e.identityOwner)
            .identityRevisionProvisionalAssociation(hash);
        f.admissionRevision = n.touchedRevision;
        f.authorityClass = living ? 1 : 3;
        f.previousRecordHash = r.previousRevisionRecord;
        f.previousValueHash = r.previousRecordHash;
        f.valueHash = r.revisedRecordHash;
        _association(e, artistId, r.signer, f);
        f.selected.admissionProof =
            keccak256(abi.encode(f.selected.admissionProof, n, chainProof, f.authorityClass));
    }

    function _payout(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 hash)
        private
        view
        returns (Facts memory f)
    {
        (W.PayoutOriginalV3 memory r, bytes32 evidenceHash) = _payoutOriginal(e, hash);
        T.PayoutDesignation memory stored =
            IStreamArtistPayoutOwner(e.payoutOwner).designationRecord(hash);
        if (
            r.recordHash != hash || stored.artistId != artistId || r.signer == address(0)
                || r.terms.payoutAccount == address(0) || r.signedAt == 0
                || r.signedAt > block.timestamp || (r.authorityClass != 1 && r.authorityClass != 3)
                || keccak256(abi.encode(stored)) != keccak256(abi.encode(r.terms))
                || H.payoutRecordForAuthority(
                        A.hashes(e), r.terms, r.signer, r.authorityClass, r.nonce, r.signedAt
                    ) != hash
        ) revert W.InvalidRecoveryRewindRecord(hash);
        T.ReplayCell memory n = A.nonce(
            e,
            artistId,
            r.nonce,
            H.payoutDigest(A.hashes(e), r.terms, T.Authorization(r.nonce, r.signedAt, new bytes(0)))
        );
        if (r.terms.previousDesignationRecordHash != 0) {
            T.PayoutDesignation memory previous = IStreamArtistPayoutOwner(e.payoutOwner)
                .designationRecord(r.terms.previousDesignationRecordHash);
            if (
                previous.artistId != artistId || previous.payoutAccount == address(0)
                    || previous.payoutAccount == r.terms.payoutAccount
            ) revert W.InvalidRecoveryRewindRecord(hash);
        }
        f.selected.originalDataHash = keccak256(abi.encode(stored, r, evidenceHash));
        f.selected.nonce = r.nonce;
        f.association = IStreamArtistPayoutTransitionOwner(e.payoutOwner)
            .payoutDesignationProvisionalAssociation(hash);
        f.admissionRevision = n.touchedRevision;
        f.authorityClass = r.authorityClass;
        f.previousRecordHash = r.terms.previousDesignationRecordHash;
        f.account = r.terms.payoutAccount;
        f.abandonmentHash =
            IStreamArtistPayoutResolutionOwner(e.payoutOwner).payoutAbandonment(hash);
        _association(e, artistId, r.signer, f);
        bytes32 abandonedProof;
        if (f.abandonmentHash != 0) {
            (D.Record memory d, T.ReplayCell memory cell) = A.dismissal(e, f.abandonmentHash);
            D.Closure memory c = IStreamArtistIdentityDismissalOwner(e.identityOwner)
                .identityTransitionClosure(artistId, f.association.transitionRecordHash);
            if (
                d.terms.artistId != artistId || !c.abandoned
                    || c.dismissalRecordHash != f.abandonmentHash
                    || f.association.transitionRecordHash == 0
                    || c.windowEndsAt != f.association.windowEndsAt
                    || cell.touchedRevision <= n.touchedRevision
            ) revert W.InvalidRecoveryRewindRecord(hash);
            abandonedProof = keccak256(abi.encode(d, cell, c));
        }
        f.selected.admissionProof =
            keccak256(abi.encode(f.selected.admissionProof, n, evidenceHash, abandonedProof));
        bytes32 continuationProof = C.payout(e, r, n);
        if (continuationProof != 0) {
            f.selected.admissionProof = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_RECOVERY_PAYOUT_RECORD_ADMISSION_V3"),
                    f.selected.admissionProof,
                    continuationProof
                )
            );
        }
    }

    function _association(
        W.EnvironmentV3 memory e,
        bytes32 artistId,
        address signer,
        Facts memory f
    ) private view {
        (f.transition, f.eligible, f.selected.admissionProof) = A.association(
            e, artistId, f.association, signer, f.authorityClass, f.admissionRevision
        );
    }

    function _standing(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 hash)
        private
        view
        returns (Facts memory f)
    {
        R.StandingRecord memory r =
            IStreamArtistRotationReads(e.identityOwner).standingRevocationRecord(hash);
        if (
            r.recordHash != hash || r.terms.artistId != artistId || r.signer == address(0)
                || (r.authorityClass != 1 && r.authorityClass != 3) || r.signedAt == 0
                || r.signedAt > block.timestamp || r.terms.revokedAddress == address(0)
                || r.terms.retiredTransitionRecordHash == 0
                || RH.standingRecordForAuthority(
                        A.hashes(e), r.terms, r.signer, r.authorityClass, r.nonce, r.signedAt
                    ) != hash
        ) revert W.InvalidRecoveryRewindRecord(hash);
        (T.ReplayCell memory admitted, bytes32 admission) = C.standing(e, r);
        // Original51 stores observed inclusion time, not the signed authorization deadline.
        // Its exact record-scoped cell is the writer certificate. Bind the same original
        // consumed nonce without inventing a deadline or rechecking today's Safe signers.
        T.ReplayCell memory n = IStreamArtistOwner(e.identityOwner)
            .replayCell(
                A.key(
                    e,
                    keccak256("identity_authority.replay.nonce_allocator"),
                    keccak256(abi.encode(artistId, r.nonce))
                )
            );
        if (
            n.commitment == 0 || n.status != 2 || n.kind != 1
                || n.touchedRevision != admitted.touchedRevision
        ) revert W.InvalidRecoveryRewindRecord(hash);
        (V.Snapshot memory v, R.TransitionState memory t) =
            A.vesting(e, artistId, r.terms.retiredTransitionRecordHash);
        (address prior, bytes32 guardian, uint64 tail) = _standingTerms(e, v);
        if (
            prior != r.terms.revokedAddress || v.oldAddress != prior || tail < 30 days
                || uint256(t.postWindowEndsAt) + tail > r.signedAt
                || admitted.touchedRevision <= v.ownerRevision
        ) revert W.InvalidRecoveryRewindRecord(hash);
        // Later retirements and later compromise markers do not erase this original admission.
        // The selector resolves its exact retirement scope against the current standing inventory.
        f.selected.originalDataHash = keccak256(abi.encode(r));
        f.selected.nonce = r.nonce;
        f.selected.admissionProof = keccak256(abi.encode(admission, n, v, t, prior, guardian, tail));
        f.transition = t;
        f.admissionRevision = admitted.touchedRevision;
        f.authorityClass = r.authorityClass;
        f.eligible = true;
        f.account = r.terms.revokedAddress;
        f.retirementHash = r.terms.retiredTransitionRecordHash;
        f.valueHash = r.terms.reasonHash;
    }

    function _standingTerms(W.EnvironmentV3 memory e, V.Snapshot memory v)
        private
        view
        returns (address prior, bytes32 guardian, uint64 tail)
    {
        if (v.operationId == 32) {
            R.RotationRecord memory r =
                IStreamArtistRotationReads(e.identityOwner).rotationRecord(v.transitionRecordHash);
            if (r.recordHash != v.transitionRecordHash || r.terms.artistId != v.artistId) {
                revert W.InvalidRecoveryRewindRecord(v.transitionRecordHash);
            }
            return (r.terms.oldAddress, r.guardianSetRecordHash, r.standingTail);
        }
        if (v.operationId == 35) {
            return IStreamArtistIdentityRecoveryOwner(e.identityOwner)
                .recoveryTransitionStanding(v.transitionRecordHash);
        }
        if (v.operationId == 40) {
            return IStreamArtistEstateOwner(e.identityOwner)
                .estateTransitionStanding(v.transitionRecordHash);
        }
        if (v.operationId == 43) {
            return IStreamArtistDormancyOwner(e.identityOwner)
                .dormancyTransitionStanding(v.transitionRecordHash);
        }
        revert W.InvalidRecoveryRewindRecord(v.transitionRecordHash);
    }

    function _payoutOriginal(W.EnvironmentV3 memory e, bytes32 hash)
        private
        view
        returns (W.PayoutOriginalV3 memory r, bytes32 evidenceHash)
    {
        (address target, bytes32 pin) =
            IStreamArtistIdentityRecoveryOwnerV3(e.identityOwner).recoveryRewindEvidenceBinding();
        if (target.code.length == 0 || pin == 0 || target.codehash != pin) {
            revert W.RecoveryRewindDependencyChanged(target);
        }
        IStreamArtistRecoveryRewindEvidence p = IStreamArtistRecoveryRewindEvidence(target);
        if (
            p.owner() != e.identityOwner || p.payoutOwner() != e.payoutOwner
                || p.artistRegistry() != e.registry || p.deploymentChainId() != e.chainId
                || p.coordinator() != e.coordinator || p.archive() != e.archive
                || p.core() != e.core || p.mintManager() != e.manager
        ) revert W.RecoveryRewindDependencyChanged(target);
        bytes32 identityPin;
        bytes32 payoutPin;
        (r, evidenceHash, identityPin, payoutPin) = p.payoutOriginalV3(hash);
        if (
            identityPin != e.identityCodeHash || payoutPin != e.payoutCodeHash || evidenceHash == 0
                || evidenceHash != W.payoutOriginalHash(e, r) || r.recordHash != hash
        ) revert W.InvalidRecoveryPayoutOriginal(hash);
    }

    function _sameRevision(bytes32 hash, T.ReplayCell memory a, T.ReplayCell memory b)
        private
        pure
    {
        if (a.touchedRevision != b.touchedRevision) revert W.InvalidRecoveryRewindRecord(hash);
    }

    function _revisionHash(W.EnvironmentV3 memory e, Doc.Record memory r, uint8 class_)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_REVISION_RECORD_V1"),
                e.chainId,
                e.registry,
                r.artistId,
                r.previousRecordHash,
                r.revisedRecordHash,
                r.signer,
                class_,
                r.nonce,
                r.signedAt
            )
        );
    }

    function _revisionParent(W.EnvironmentV3 memory e, Doc.Record memory r) private view {
        if (r.previousRevisionRecord == 0) {
            if (
                IStreamArtistIdentityOwner(e.identityOwner).identity(r.artistId).identityRecordHash
                    != r.previousRecordHash
            ) revert W.InvalidRecoveryRewindRecord(r.recordHash);
        } else {
            Doc.Record memory p = IStreamArtistIdentityRevisionReads(e.identityOwner)
                .identityRevisionRecord(r.previousRevisionRecord);
            if (
                p.recordHash != r.previousRevisionRecord || p.artistId != r.artistId
                    || p.revisedRecordHash != r.previousRecordHash || p.recordHash == r.recordHash
            ) revert W.InvalidRecoveryRewindRecord(r.recordHash);
        }
    }

    function _operation(W.RecordKind kind) private pure returns (uint16) {
        if (kind == W.RecordKind.SUCCESSOR_DESIGNATION) return 36;
        if (kind == W.RecordKind.ESTATE_DIRECTIVE) return 37;
        if (kind == W.RecordKind.IDENTITY_REVISION) return 25;
        if (kind == W.RecordKind.PAYOUT_DESIGNATION) return 18;
        if (kind == W.RecordKind.STEWARD_SANCTION_GRANT) return 19;
        if (kind == W.RecordKind.PRIOR_ADDRESS_STANDING_REVOCATION) return 51;
        revert W.InvalidRecoveryRewindRecord(bytes32(0));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveryRewindSelectionState as Store
} from "./StreamArtistRecoveryRewindSelectionState.sol";
import {
    StreamArtistRecoveryRewindSelectionScan as Scan
} from "./StreamArtistRecoveryRewindSelectionScan.sol";
import {
    StreamArtistRecoveryRewindEnvironment as Environment
} from "./StreamArtistRecoveryRewindEnvironment.sol";
import {
    StreamArtistRecoveryRewindTypes as W
} from "../../interfaces/stream/artist/StreamArtistRecoveryRewindTypes.sol";
import {
    StreamArtistGuardianHistoryTypes as GH
} from "../../interfaces/stream/artist/StreamArtistGuardianHistoryTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistRecoveryActionTypes as A
} from "../../interfaces/stream/artist/StreamArtistRecoveryActionTypes.sol";
import {
    IStreamArtistRecoveryRewindSelection
} from "../../interfaces/stream/artist/IStreamArtistRecoveryRewindSelection.sol";
import {
    IStreamArtistRecoveryRewindEvidence
} from "../../interfaces/stream/artist/IStreamArtistRecoveryRewindEvidence.sol";
import {
    IStreamArtistIdentityRecoveryOwnerV3
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecoveryV3.sol";
import {
    IStreamArtistRecoveryPayoutOwnerV3
} from "../../interfaces/stream/artist/IStreamArtistRecoveryPayoutOwnerV3.sol";
import {
    IStreamArtistRecoveryActionOwner
} from "../../interfaces/stream/artist/IStreamArtistRecoveryAction.sol";
import {
    IStreamArtistGuardianHistory
} from "../../interfaces/stream/artist/IStreamArtistGuardianHistory.sol";
import {
    IStreamArtistNativeReceipts
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";

/// @notice Resumable fixed-owner election from complete original native receipt prefixes.
/// @dev Preparation facts only. Historical getters preserve the completed scan; requireSelection
/// additionally enforces exact current source snapshots, including the separately sealed op65534.
contract StreamArtistRecoveryRewindSelection is IStreamArtistRecoveryRewindSelection {
    address public immutable override owner;
    address public immutable override artistRegistry;
    address public immutable override coordinator;
    uint256 public immutable override deploymentChainId;
    Store.State private _state;

    event RecoveryRewindSelectionBegun(bytes32 indexed key, bytes32 indexed manifestHash);
    event RecoveryRewindSelectionProgress(
        bytes32 indexed key, uint256 identityProcessed, uint256 payoutProcessed, bool complete
    );
    event RecoveryRewindPreparationSealed(
        bytes32 indexed key, bytes32 indexed actionId, bytes32 commitment
    );

    constructor(address owner_, address registry_, address coordinator_) {
        // The fixed owner and Coordinator can still be constructing.
        if (
            owner_ == address(0) || registry_ == address(0) || coordinator_ == address(0)
                || owner_ == registry_ || owner_ == coordinator_ || registry_ == coordinator_
        ) {
            revert W.InvalidRecoveryRewindSelection(bytes32(0));
        }
        owner = owner_;
        artistRegistry = registry_;
        coordinator = coordinator_;
        deploymentChainId = block.chainid;
    }

    function payoutOwner() external view override returns (address) {
        return _environment().payoutOwner;
    }

    function beginSelectionV3(bytes32 manifestHash) external override returns (bytes32 key) {
        key = _state.manifestKeys[manifestHash];
        if (key != 0) {
            _requireCurrent(key);
            return key;
        }
        W.EnvironmentV3 memory e = _environment();
        W.ResolutionManifestV3 memory m = _manifest(e, manifestHash);
        _prefix(e.identityOwner, m.identity, m.identity.snapshot, manifestHash);
        _prefix(e.payoutOwner, m.payout, m.payout.snapshot, manifestHash);
        W.BasisV3 memory b = _basis(e, manifestHash, m);
        key = W.selectionKey(e, b);
        if (key == 0 || _state.bases[key].identity.artistId != 0) {
            revert W.InvalidRecoveryRewindSelection(key);
        }
        _state.manifestKeys[manifestHash] = key;
        _state.environments[key] = e;
        _state.bases[key] = b;
        _state.excluded[key] = m.supersededRecords;
        for (uint256 i; i < m.supersededRecords.length; ++i) {
            _state.excludedIndex[key][m.supersededRecords[i].recordHash] = uint8(i + 1);
        }
        emit RecoveryRewindSelectionBegun(key, manifestHash);
    }

    function continueSelectionV3(bytes32 key, uint64 maximumRecords)
        external
        override
        returns (W.ProgressV3 memory)
    {
        if (maximumRecords == 0) revert W.InvalidRecoveryRewindSelection(key);
        _requireCurrent(key);
        if (_state.progress[key].complete) return _state.progress[key];
        W.BasisV3 storage b = _state.bases[key];
        uint64 remaining = maximumRecords;
        while (
            remaining != 0
                && _state.progress[key].identityProcessed < b.identity.identity.receiptCount
        ) {
            Scan.identity(_state, key, _state.progress[key].identityProcessed);
            --remaining;
        }
        while (remaining != 0 && _state.progress[key].payoutProcessed < b.payout.receiptCount) {
            Scan.payout(_state, key, _state.progress[key].payoutProcessed);
            --remaining;
        }
        if (
            _state.progress[key].identityProcessed == b.identity.identity.receiptCount
                && _state.progress[key].payoutProcessed == b.payout.receiptCount
        ) Scan.finish(_state, key);
        W.ProgressV3 memory p = _state.progress[key];
        emit RecoveryRewindSelectionProgress(
            key, p.identityProcessed, p.payoutProcessed, p.complete
        );
        return p;
    }

    function requireSelectionV3(bytes32 manifestHash)
        external
        view
        override
        returns (W.ResultV3 memory)
    {
        bytes32 key = _state.manifestKeys[manifestHash];
        if (key == 0) {
            W.EnvironmentV3 memory e = _environment();
            W.ResolutionManifestV3 memory m = _manifest(e, manifestHash);
            _prefix(e.identityOwner, m.identity, m.identity.snapshot, manifestHash);
            _prefix(e.payoutOwner, m.payout, m.payout.snapshot, manifestHash);
            key = W.selectionKey(e, _basis(e, manifestHash, m));
            revert W.InvalidRecoveryRewindSelection(key);
        }
        _requireCurrent(key);
        return _completed(key);
    }

    function selectionV3(bytes32 key)
        external
        view
        override
        returns (W.BasisV3 memory, W.ProgressV3 memory)
    {
        return (_state.bases[key], _state.progress[key]);
    }

    function selectionResultV3(bytes32 key) external view override returns (W.ResultV3 memory) {
        return _completed(key);
    }

    function selectionRecordV3(bytes32 key, bytes32 recordHash)
        external
        view
        override
        returns (W.RecordKind, W.SelectedRecordV3 memory, bool retained, bool eligible)
    {
        _completed(key);
        if (!_state.admitted[key][recordHash]) revert W.InvalidRecoveryRewindSelection(key);
        return (
            _state.kinds[key][recordHash],
            _state.records[key][recordHash].selected,
            _state.retained[key][recordHash],
            _state.records[key][recordHash].eligible
        );
    }

    function retainedMemberV3(bytes32 key, address actor) external view override returns (bool) {
        _completed(key);
        return actor != address(0) && _state.retainedMembers[key][actor];
    }

    function preparationSealV3(bytes32 key)
        external
        view
        override
        returns (W.PreparationSealV3 memory)
    {
        return _state.seals[key];
    }

    function sealPreparationV3(bytes32 manifestHash, bytes32 actionId, bytes32 associationHash)
        external
        override
        returns (bytes32)
    {
        if (msg.sender != coordinator || actionId == 0 || associationHash == 0) {
            revert W.InvalidRecoveryRewindPreparation(actionId);
        }
        bytes32 key = _state.manifestKeys[manifestHash];
        W.ResultV3 memory result = _completed(key);
        W.BasisV3 memory b = _state.bases[key];
        W.EnvironmentV3 memory e = _environment();
        _environmentMatch(key, e);
        _prefix(e.payoutOwner, b.payout, b.payout.snapshot, key);
        if (
            IStreamArtistNativeReceipts(owner).artistNativeReceiptCount()
                != b.identity.identity.receiptCount
        ) {
            revert W.InvalidRecoveryRewindPreparation(actionId);
        }
        T.Snapshot memory afterPreparation = IStreamArtistOwner(owner).ownerStateSnapshotV2();
        if (
            b.identity.identity.snapshot.revision == type(uint64).max
                || afterPreparation.revision != b.identity.identity.snapshot.revision + 1
                || afterPreparation.domainId != b.identity.identity.snapshot.domainId
                || afterPreparation.stateRoot == 0 || afterPreparation.recordChainTip == 0
        ) {
            revert W.InvalidRecoveryRewindPreparation(actionId);
        }
        W.ResolutionManifestV3 memory m = _manifest(e, manifestHash);
        _basisMatch(key, e, _basis(e, manifestHash, m), m.supersededRecords);
        W.EvidenceStateV3 memory evidence =
            _prepared(key, actionId, associationHash, result, afterPreparation);
        W.PreparationSealV3 memory seal = W.PreparationSealV3(
            manifestHash,
            key,
            actionId,
            associationHash,
            b.identity.identity,
            afterPreparation,
            b.payout,
            keccak256(abi.encode(evidence)),
            bytes32(0)
        );
        seal.commitment = W.preparationSealHash(e, seal);
        if (_state.seals[key].commitment != 0) {
            if (keccak256(abi.encode(_state.seals[key])) != keccak256(abi.encode(seal))) {
                revert W.InvalidRecoveryRewindPreparation(actionId);
            }
            return seal.commitment;
        }
        _state.seals[key] = seal;
        emit RecoveryRewindPreparationSealed(key, actionId, seal.commitment);
        return seal.commitment;
    }

    function _prepared(
        bytes32 key,
        bytes32 actionId,
        bytes32 associationHash,
        W.ResultV3 memory result,
        T.Snapshot memory afterPreparation
    ) private view returns (W.EvidenceStateV3 memory evidence) {
        W.BasisV3 memory b = _state.bases[key];
        (A.Association memory prepared, A.Veto memory veto, bytes32 executed,) = IStreamArtistRecoveryActionOwner(
                owner
            ).identityRecoveryActionState(b.identity.artistId, bytes32(0));
        A.Veto memory emptyVeto;
        if (
            prepared.artistId != b.identity.artistId || prepared.action.actionId != actionId
                || prepared.associationHash != associationHash
                || prepared.ownerRevision != afterPreparation.revision || prepared.requestHash == 0
                || prepared.acceptanceHash == 0 || prepared.contextHash == 0
                || prepared.preparedBy == address(0) || prepared.preparedAt == 0 || executed != 0
                || keccak256(abi.encode(veto)) != keccak256(abi.encode(emptyVeto))
        ) {
            revert W.InvalidRecoveryRewindPreparation(actionId);
        }
        evidence = IStreamArtistIdentityRecoveryOwnerV3(owner)
            .identityRecoveryEvidenceStateV3(b.identity.artistId, actionId);
        if (
            evidence.manifestHash != b.identity.manifestHash || evidence.sourceKey != key
                || evidence.sourceCommitment != b.sourceCommitment
                || evidence.selectionCommitment != result.commitment
                || evidence.policyCommitment == 0 || evidence.requiredRole == 0
                || evidence.associationHash != associationHash
                || evidence.sources.associationHash != associationHash
                || keccak256(abi.encode(evidence.sources.identityBefore))
                    != keccak256(abi.encode(b.identity.identity))
                || keccak256(abi.encode(evidence.sources.payout)) != keccak256(abi.encode(b.payout))
        ) {
            revert W.InvalidRecoveryRewindPreparation(actionId);
        }
    }

    function _requireCurrent(bytes32 key) private view {
        W.BasisV3 memory saved = _state.bases[key];
        if (key == 0 || saved.identity.artistId == 0) revert W.InvalidRecoveryRewindSelection(key);
        W.EnvironmentV3 memory e = _environment();
        _environmentMatch(key, e);
        W.PreparationSealV3 memory seal = _state.seals[key];
        T.Snapshot memory expected = saved.identity.identity.snapshot;
        if (seal.commitment != 0) {
            if (
                seal.sourceKey != key || seal.manifestHash != saved.identity.manifestHash
                    || seal.commitment != W.preparationSealHash(e, seal)
            ) revert W.InvalidRecoveryRewindSelection(key);
            expected = seal.identityAfterPreparation;
        }
        // Check before calling the owner basis hook so stale known keys have one exact error.
        _prefix(owner, saved.identity.identity, expected, key);
        _prefix(e.payoutOwner, saved.payout, saved.payout.snapshot, key);
        W.ResolutionManifestV3 memory m = _manifest(e, saved.identity.manifestHash);
        _basisMatch(key, e, _basis(e, saved.identity.manifestHash, m), m.supersededRecords);
        if (seal.commitment != 0) {
            W.EvidenceStateV3 memory evidence =
                _prepared(key, seal.actionId, seal.associationHash, _completed(key), expected);
            if (keccak256(abi.encode(evidence)) != seal.evidenceStateHash) {
                revert W.InvalidRecoveryRewindSelection(key);
            }
        }
    }

    function _completed(bytes32 key) private view returns (W.ResultV3 memory result) {
        W.BasisV3 memory b = _state.bases[key];
        W.ProgressV3 memory p = _state.progress[key];
        W.EnvironmentV3 memory e = _environment();
        _environmentMatch(key, e);
        result = _state.results[key];
        if (
            b.identity.artistId == 0 || key != W.selectionKey(e, b) || !p.complete
                || b.sourceCommitment != W.selectionSourceHash(e, b)
                || p.identityProcessed != b.identity.identity.receiptCount
                || p.payoutProcessed != b.payout.receiptCount
                || p.guardiansProcessed != b.identity.guardianHistory.count
                || p.seenExclusions != (uint256(1) << _state.excluded[key].length) - 1
                || result.sourceKey != key || result.manifestHash != b.identity.manifestHash
                || result.sourceCommitment != b.sourceCommitment
                || result.guardians.sourceKey != key
                || result.inventoryCommitment
                    != W.selectionInventoryHash(e, b.identity.inventory, b.payoutInventory)
                || result.commitment == 0 || result.commitment != p.resultCommitment
                || result.commitment != W.selectionResultHash(e, result)
        ) revert W.InvalidRecoveryRewindSelection(key);
    }

    function _basis(W.EnvironmentV3 memory e, bytes32 manifestHash, W.ResolutionManifestV3 memory m)
        private
        view
        returns (W.BasisV3 memory b)
    {
        b.identity = IStreamArtistIdentityRecoveryOwnerV3(owner).recoveryRewindBasisV3(manifestHash);
        b.payoutCodeHash = e.payoutCodeHash;
        b.payout = m.payout;
        b.payoutInventory =
            IStreamArtistRecoveryPayoutOwnerV3(e.payoutOwner).payoutRewindInventoryV3(m.artistId);
        (GH.Head memory head,,,) = IStreamArtistGuardianHistory(owner)
            .guardianHistoryState(m.artistId, 0, address(0), bytes32(0));
        W.IdentityInventoryV3 memory inventory =
            IStreamArtistIdentityRecoveryOwnerV3(owner).recoveryRewindInventoryV3(m.artistId);
        if (
            b.identity.manifestHash != manifestHash || b.identity.artistId != m.artistId
                || m.artistId == 0 || b.identity.ownerCodeHash != e.identityCodeHash
                || b.identity.sourceCommitment == 0
                || keccak256(abi.encode(b.identity.identity)) != keccak256(abi.encode(m.identity))
                || keccak256(abi.encode(head)) != keccak256(abi.encode(b.identity.guardianHistory))
                || keccak256(abi.encode(inventory)) != keccak256(abi.encode(b.identity.inventory))
                || (head.count == 0
                        ? head.commitment != 0 || head.ownerRevision != 0
                        : head.commitment == 0 || head.ownerRevision == 0
                        || head.ownerRevision > m.identity.snapshot.revision)
        ) {
            revert W.InvalidRecoveryRewindSelection(manifestHash);
        }
        b.sourceCommitment = W.selectionSourceHash(e, b);
    }

    function _basisMatch(
        bytes32 key,
        W.EnvironmentV3 memory e,
        W.BasisV3 memory b,
        W.RecordReference[] memory excluded
    ) private view {
        if (
            key != W.selectionKey(e, b)
                || keccak256(abi.encode(_state.bases[key])) != keccak256(abi.encode(b))
                || keccak256(abi.encode(_state.excluded[key])) != keccak256(abi.encode(excluded))
        ) {
            revert W.InvalidRecoveryRewindSelection(key);
        }
    }

    function _prefix(
        address target,
        W.ReceiptPrefix memory prefix,
        T.Snapshot memory expected,
        bytes32 failureKey
    ) private view {
        if (
            keccak256(abi.encode(IStreamArtistOwner(target).ownerStateSnapshotV2()))
                    != keccak256(abi.encode(expected))
                || IStreamArtistNativeReceipts(target).artistNativeReceiptCount()
                    != prefix.receiptCount
        ) {
            revert W.InvalidRecoveryRewindSelection(failureKey);
        }
    }

    function _environmentMatch(bytes32 key, W.EnvironmentV3 memory e) private view {
        if (key == 0 || keccak256(abi.encode(_state.environments[key])) != keccak256(abi.encode(e)))
        {
            revert W.InvalidRecoveryRewindSelection(key);
        }
    }

    function _environment() private view returns (W.EnvironmentV3 memory e) {
        if (block.chainid != deploymentChainId || owner.code.length == 0) {
            revert W.RecoveryRewindDependencyChanged(owner);
        }
        IStreamArtistOwner o = IStreamArtistOwner(owner);
        e = Environment.fromFixed(
            owner, artistRegistry, coordinator, o.archiveV2(), o.core(), o.mintManager()
        );
    }

    function _manifest(W.EnvironmentV3 memory e, bytes32 hash)
        private
        view
        returns (W.ResolutionManifestV3 memory m)
    {
        (address target, bytes32 pin) =
            IStreamArtistIdentityRecoveryOwnerV3(owner).recoveryRewindEvidenceBinding();
        if (target.code.length == 0 || pin == 0 || target.codehash != pin) {
            revert W.RecoveryRewindDependencyChanged(target);
        }
        IStreamArtistRecoveryRewindEvidence publisher = IStreamArtistRecoveryRewindEvidence(target);
        if (
            publisher.owner() != owner || publisher.payoutOwner() != e.payoutOwner
                || publisher.artistRegistry() != artistRegistry
                || publisher.deploymentChainId() != deploymentChainId
                || publisher.coordinator() != coordinator || publisher.archive() != e.archive
                || publisher.core() != e.core || publisher.mintManager() != e.manager
        ) revert W.RecoveryRewindDependencyChanged(target);
        bytes32 identityPin;
        bytes32 payoutPin;
        (m, identityPin, payoutPin) = publisher.resolutionManifestV3(hash);
        if (
            hash == 0 || identityPin != e.identityCodeHash || payoutPin != e.payoutCodeHash
                || hash != W.manifestHash(e, m) || m.supersededRecords.length > W.MAX_SUPERSESSIONS
        ) {
            revert W.InvalidRecoveryRewindSelection(hash);
        }
        bytes32 previous;
        for (uint256 i; i < m.supersededRecords.length; ++i) {
            if (m.supersededRecords[i].recordHash <= previous) {
                revert W.InvalidRecoveryRewindSelection(hash);
            }
            previous = m.supersededRecords[i].recordHash;
        }
    }
}

