                c.manifestHash,
                c.planCommitment,
                c.designationRecordHash,
                c.pairedDirectiveRecordHash,
                c.forbiddenDirectiveRecordHash,
                c.authorityAddress,
                c.effectiveCapabilities
            )
        );
    }
}

